// The MHPCO's register of the policies opened so far in a scenario. A claim
// names the policy it draws on by the step that opened it, and the MHPCO
// refuses a claim that names a step which opened none.
class PolicyRegister {
  private readonly policies = new Map<number, Policy>();

  open(openedByStep: number, policy: Policy): void {
    this.policies.set(openedByStep, policy);
  }

  policyOpenedBy(openedByStep: number): Policy {
    const policy = this.policies.get(openedByStep);
    if (policy === undefined) {
      throw new Error(`step ${openedByStep} did not create a policy`);
    }
    return policy;
  }
}

// The MHPCO settles a scenario's steps in order for a single customer: each
// quote opens a policy the later claims draw on, and every quote after the
// customer's first is a follow-up contract.
export function runScenario(scenario: Scenario): StepResult[] {
  const register = new PolicyRegister();
  let previousContracts = 0;
  return scenario.steps.map((step, stepIndex) => {
    if (step.op === "quote") {
      const premium = quote(scenario.customer, step.items, previousContracts);
      previousContracts += 1;
      register.open(stepIndex, openPolicy(step.items));
      return { premium };
    }
    const result = claim(register.policyOpenedBy(step.policy), step.incident);
    register.open(step.policy, result.policy);
    return { payout: result.payout, remainingCap: result.remainingCap };
  });
}

